const payload = $input.item.json.body || $input.item.json;
let title = 'Alert Notification';
let headerColor = '#3b82f6';
let messageLines = [];
let recipient = '';

const EMAIL_WH = 'alienmaymua@gmail.com';
const EMAIL_QC = 'hoanganhle0320@gmail.com';
const EMAIL_PM = 'nhuyenmy4@gmail.com, vuphuong05012005@gmail.com';

if (payload.event === 'material-request-alert' || payload.request_id) {
  // 1. PM gửi request -> Gửi cho WH (Warehouse)
  recipient = EMAIL_WH;
  title = '📦 THÔNG BÁO: YÊU CẦU VẬT TƯ SẢN XUẤT (TỪ PM)';
  headerColor = '#8b5cf6';
  messageLines = [
    `<b>Mã yêu cầu:</b> #${payload.request_id || 'NEW'}`,
    `<b>Hành động:</b> ${payload.action || 'Tạo mới'}`,
    `<b>Trạng thái:</b> ${payload.status || 'Pending'}`
  ];
  if (payload.material_id) messageLines.push(`<b>Mã vật tư:</b> ${payload.material_id}`);
  if (payload.quantity_kg) messageLines.push(`<b>Số lượng:</b> ${payload.quantity_kg} kg`);
  if (payload.needed_date) messageLines.push(`<b>Ngày cần:</b> ${payload.needed_date}`);
  if (payload.priority) messageLines.push(`<b>Mức ưu tiên:</b> ${payload.priority}`);
  if (payload.notes) messageLines.push(`<b>Ghi chú:</b> ${payload.notes}`);
} else if (payload.event === 'stock-alert' || payload.alert_type || payload.available_stock_kg !== undefined) {
  // 2. WH chỉnh hàng về 0 hoặc <=100 -> Gửi cho PM
  recipient = EMAIL_PM;
  const isOOS = payload.alert_type === 'out_of_stock' || payload.available_stock_kg <= 0;
  title = isOOS ? '🚨 KHẨN CẤP: LÔ HÀNG HẾT HÀNG TỒN KHO (0 KG)' : '⚠️ CẢNH BÁO: TỒN KHO THẤP (<= 100 KG)';
  headerColor = isOOS ? '#dc2626' : '#f59e0b';
  messageLines = [
    `<b>Mã lô hàng:</b> ${payload.batch_id || 'N/A'}`,
    `<b>Tồn kho khả dụng còn lại:</b> ${payload.available_stock_kg !== undefined ? payload.available_stock_kg : 0} kg`,
    `<b>Mức cảnh báo:</b> ${isOOS ? 'Hết hàng (0 kg)' : 'Tồn kho thấp (<= 100 kg)'}`
  ];
} else if (payload.event === 'qc-alert' || payload.destination || payload.actual_yield_pct !== undefined) {
  // 3. QC duyệt hoặc từ chối sản phẩm -> Gửi cho WH + PM
  recipient = `${EMAIL_WH}, ${EMAIL_PM}`;
  const isRejected = payload.status === 'Rejected';
  title = isRejected ? '⚠️ CẢNH BÁO: QC TỪ CHỐI LÔ HÀNG (REJECTED)' : '✅ DUYỆT QC: LÔ HÀNG ĐẠT CHUẨN (APPROVED)';
  headerColor = isRejected ? '#ef4444' : '#22c55e';
  messageLines = [
    `<b>Mã lô hàng:</b> ${payload.batch_id || 'N/A'}`,
    `<b>Trạng thái QC:</b> ${payload.status || 'N/A'}`,
    `<b>Đích chuyển:</b> ${payload.destination || 'N/A'}`,
    `<b>Trọng lượng khả dụng:</b> ${payload.usable_weight_kg || 0} kg`,
    `<b>Số lượng loại bỏ:</b> ${payload.rejected_qty_kg || 0} kg`,
    `<b>Tỷ lệ thu hồi (Yield):</b> ${payload.actual_yield_pct || 0}%`,
    `<b>Lý do:</b> ${payload.reason || 'N/A'}`
  ];
}

const listItems = messageLines.map(line => `<li style="padding: 8px 0; border-bottom: 1px solid #f3f4f6;">${line}</li>`).join('');
const htmlBody = `<div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e5e7eb; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.05);"><div style="background-color: ${headerColor}; color: #ffffff; padding: 20px; text-align: center;"><h2 style="margin: 0; font-size: 20px;">${title}</h2></div><div style="padding: 24px; background-color: #ffffff; color: #1f2937; font-size: 15px; line-height: 1.6;"><ul style="list-style: none; padding: 0; margin: 0;">${listItems}</ul></div><div style="background-color: #f9fafb; padding: 12px 20px; text-align: center; font-size: 12px; color: #6b7280; border-top: 1px solid #e5e7eb;">Thông báo tự động từ Hệ thống Quản lý Kho & Sản xuất (Capstone Project 2)</div></div>`;

return {
  json: {
    subject: `[HỆ THỐNG KHO] ${title}`,
    recipient_email: recipient,
    htmlBody: htmlBody,
    payload: payload
  }
};
